const hoy = $now.setZone('Europe/Madrid').startOf('day');
const lunesActual = hoy.startOf('week');
const desde = lunesActual.minus({ days: 7 });
const hasta = lunesActual.minus({ seconds: 1 });
const f = d => d.toFormat('dd/MM/yyyy');
return [{ json: {
  desde_ts: Math.floor(desde.toSeconds()),
  hasta_ts: Math.floor(hasta.toSeconds()),
  desde: f(desde),
  hasta: f(hasta),
  etiqueta: f(desde) + ' - ' + f(hasta)
} }];

const sem = $('Calcular semana').first().json;
const crudo = $('Open WebUI usuarios').all().map(i => i.json);
const lista = (crudo.length === 1 && Array.isArray(crudo[0].users)) ? crudo[0].users : crudo;
const porId = {};
for (const u of lista) { if (u && u.id) porId[u.id] = u; }
const chats = $input.all().map(i => i.json).filter(c => c && c.chat && c.user_id);

const NL = String.fromCharCode(10);
const ERR = /(error|exception|traceback|timeout|forbidden|unauthorized|n8n ha respondido|falta configurar|no he podido|no se pudo)/i;
const seg = v => (v > 1e12 ? v / 1000 : v);
const txt = v => typeof v === 'string' ? v : (Array.isArray(v) ? v.map(x => (x && (x.text || x.content)) || '').join(' ') : (v ? JSON.stringify(v) : ''));
const corto = (s, n) => { const t = String(s ?? '').split(NL).join(' ').trim(); return t.length > n ? t.slice(0, n) + '...' : t; };
const fecha = ts => DateTime.fromSeconds(ts).setZone('Europe/Madrid').toFormat('dd/MM HH:mm');

const SYSTEM = [
  'Eres un analista de uso de un asistente de IA corporativo de Diania Logistics (transporte por carretera). Recibes la actividad de UN empleado durante una semana: sus preguntas, las respuestas del asistente y las llamadas a herramientas.',
  'Responde SOLO con un JSON valido, sin texto adicional ni markdown, con exactamente esta forma:',
  '{"resumen":"2-3 frases sobre para que ha usado el asistente","temas":["tema corto"],"preguntas_recurrentes":[{"pregunta":"pregunta o tipo de peticion que repite","veces":2}],"errores_de_uso":[{"tipo":"etiqueta corta","detalle":"que paso, citando brevemente la pregunta","sugerencia":"que deberia hacer"}],"errores_tecnicos":[{"herramienta":"nombre","detalle":"que fallo"}]}',
  'Definiciones:',
  '- preguntas_recurrentes: peticiones iguales o muy parecidas hechas varias veces (en el mismo chat o en chats distintos). Agrupalas e indica cuantas veces. Si ninguna se repite, array vacio.',
  '- errores_de_uso: problemas atribuibles a como se usa el asistente: preguntas ambiguas o sin los datos necesarios (fechas, cliente, numero de pedido o matricula), repetir intentos que no funcionan sin cambiar nada, pedir algo que las herramientas no cubren, mezclar varias peticiones en una, pegar datos sensibles (contrasenas, claves) o dar por buena una respuesta sin comprobarla.',
  '- errores_tecnicos: fallos del sistema o de las herramientas (errores HTTP, herramienta que no responde, respuestas del tipo no he podido consultar). NO los pongas en errores_de_uso.',
  'No inventes nada: si no hay errores o preguntas recurrentes, devuelve arrays vacios. Escribe en espanol, tono neutro y profesional, breve.'
].join(NL);

const porUsuario = {};
for (const c of chats) {
  const todos = (c.chat.history && c.chat.history.messages) ? Object.values(c.chat.history.messages) : (Array.isArray(c.chat.messages) ? c.chat.messages : []);
  const msgs = todos.filter(m => m && m.timestamp && seg(m.timestamp) >= sem.desde_ts && seg(m.timestamp) <= sem.hasta_ts).sort((a, b) => seg(a.timestamp) - seg(b.timestamp));
  if (msgs.length === 0) continue;
  const u = porUsuario[c.user_id] = porUsuario[c.user_id] || { chats: [], stats: { chats: 0, mensajes: 0, herramientas: {}, errores_herramienta: 0, errores_sistema: 0, valoraciones_negativas: 0, valoraciones_positivas: 0 } };
  u.stats.chats += 1;
  const ch = { titulo: corto(c.title || 'Sin titulo', 80), inicio: seg(msgs[0].timestamp), modelo: '', turnos: [] };
  for (const m of msgs) {
    if (m.role === 'user') {
      u.stats.mensajes += 1;
      ch.turnos.push({ r: 'u', t: txt(m.content) });
    } else if (m.role === 'assistant') {
      if (m.model) ch.modelo = m.model;
      const salidas = {};
      for (const o of (m.output || [])) { if (o && o.type === 'function_call_output') salidas[o.call_id] = txt(o.output); }
      const llamadas = [];
      for (const o of (m.output || [])) {
        if (!o || o.type !== 'function_call' || o.hidden) continue;
        const nombre = o.name || 'herramienta';
        const salida = salidas[o.call_id] || '';
        const fallo = ERR.test(corto(salida, 150));
        const h = u.stats.herramientas[nombre] = u.stats.herramientas[nombre] || { llamadas: 0, errores: 0 };
        h.llamadas += 1;
        if (fallo) { h.errores += 1; u.stats.errores_herramienta += 1; }
        llamadas.push({ nombre, fallo, salida: fallo ? corto(salida, 160) : '' });
      }
      let err = '';
      if (m.error) { u.stats.errores_sistema += 1; err = corto(typeof m.error === 'string' ? m.error : (m.error.content || JSON.stringify(m.error)), 160); }
      let valoracion = '';
      const rating = m.annotation && m.annotation.rating;
      if (rating === -1) { u.stats.valoraciones_negativas += 1; valoracion = 'negativa' + (m.annotation.reason ? ': ' + corto(m.annotation.reason, 80) : ''); }
      if (rating === 1) { u.stats.valoraciones_positivas += 1; }
      ch.turnos.push({ r: 'a', t: txt(m.content), llamadas, err, valoracion });
    }
  }
  u.chats.push(ch);
}

const armar = (datos, nu, na) => {
  const partes = [];
  for (const ch of datos.chats.sort((a, b) => a.inicio - b.inicio)) {
    partes.push('### Chat "' + ch.titulo + '" (' + fecha(ch.inicio) + ', modelo ' + (ch.modelo || '?') + ')');
    for (const t of ch.turnos) {
      if (t.r === 'u') { partes.push('USUARIO: ' + corto(t.t, nu)); continue; }
      for (const l of t.llamadas) partes.push('[herramienta ' + l.nombre + (l.fallo ? ' -> POSIBLE ERROR: ' + l.salida : ' -> ok') + ']');
      if (t.err) partes.push('[ERROR del sistema: ' + t.err + ']');
      if (t.valoracion) partes.push('[valoracion ' + t.valoracion + ']');
      partes.push('ASISTENTE: ' + corto(t.t, na));
    }
  }
  return partes.join(NL);
};

const items = [];
for (const id of Object.keys(porUsuario)) {
  const datos = porUsuario[id];
  const info = porId[id] || {};
  const nombre = info.name || '(usuario eliminado)';
  const grupos = (info.groups || []).map(g => (typeof g === 'string' ? g : g.name)).filter(Boolean);
  let transcripcion = armar(datos, 600, 300);
  if (transcripcion.length > 14000) transcripcion = armar(datos, 350, 120);
  if (transcripcion.length > 14000) transcripcion = transcripcion.slice(0, 14000) + NL + '[transcripcion truncada]';
  const s = datos.stats;
  const prompt = 'Empleado: ' + nombre + (grupos.length ? ' (grupos: ' + grupos.join(', ') + ')' : '') + NL
    + 'Semana: ' + sem.etiqueta + NL
    + 'Estadisticas: ' + s.chats + ' chats, ' + s.mensajes + ' mensajes del usuario, ' + s.errores_herramienta + ' posibles errores de herramienta, ' + s.errores_sistema + ' errores del sistema, ' + s.valoraciones_negativas + ' valoraciones negativas.' + NL + NL
    + 'Actividad:' + NL + transcripcion;
  items.push({ json: { sin_actividad: false, user_id: id, nombre, email: info.email || '', grupos, semana: sem.etiqueta, stats: s, system: SYSTEM, prompt } });
}

if (items.length === 0) {
  return [{ json: { sin_actividad: true, semana: sem.etiqueta, desde: sem.desde, hasta: sem.hasta } }];
}
items.sort((a, b) => a.json.nombre.localeCompare(b.json.nombre));
return items;

const prep = $('Preparar por usuario').all().map(i => i.json);
const NL = String.fromCharCode(10);
const sacarJson = (resp) => {
  const t = resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
  if (typeof t !== 'string') return null;
  const a = t.indexOf('{');
  const b = t.lastIndexOf('}');
  if (a < 0 || b <= a) return { resumen: t.slice(0, 600) };
  try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { return { resumen: t.slice(0, 600) }; }
};
const entrada = $input.all();
const usuarios = entrada.map((it, i) => {
  const idx = (it.pairedItem && typeof it.pairedItem.item === 'number') ? it.pairedItem.item : i;
  const p = prep[idx] || {};
  const err = it.json && it.json.error;
  const analisis = err ? null : sacarJson(it.json);
  return {
    user_id: p.user_id, nombre: p.nombre, email: p.email, grupos: p.grupos, stats: p.stats,
    analisis, fallo_llm: err ? String(err.message || err).slice(0, 200) : (analisis ? '' : 'respuesta vacia')
  };
});

const lineas = [];
for (const u of usuarios) {
  const a = u.analisis || {};
  lineas.push('## ' + u.nombre + ' (' + (u.grupos || []).join(', ') + ') - ' + (u.stats ? u.stats.mensajes : 0) + ' mensajes');
  lineas.push('Temas: ' + (a.temas || []).join('; '));
  lineas.push('Preguntas recurrentes: ' + (a.preguntas_recurrentes || []).map(q => q.pregunta + ' (x' + q.veces + ')').join('; '));
  lineas.push('Errores de uso: ' + (a.errores_de_uso || []).map(e => e.tipo + ': ' + e.detalle).join('; '));
  lineas.push('Errores tecnicos: ' + (a.errores_tecnicos || []).map(e => (e.herramienta || '') + ': ' + e.detalle).join('; '));
}
let prompt_global = lineas.join(NL);
if (prompt_global.length > 14000) prompt_global = prompt_global.slice(0, 14000) + NL + '[truncado]';

const system_global = [
  'Eres un analista de uso de un asistente de IA corporativo de Diania Logistics. Recibes el resumen semanal de la actividad de cada empleado. Busca patrones en el conjunto del equipo.',
  'Responde SOLO con un JSON valido, sin texto adicional ni markdown, con esta forma:',
  '{"resumen_equipo":"3-4 frases sobre como se ha usado el asistente esta semana","preguntas_recurrentes_equipo":[{"pregunta":"peticion que se repite entre varias personas","usuarios":["nombre"],"veces":3}],"errores_frecuentes":[{"tipo":"etiqueta","detalle":"que pasa","sugerencia":"formacion o mejora recomendada"}],"mejoras_sugeridas":["accion concreta: herramienta nueva, cambio en el prompt, formacion..."]}',
  'No inventes nada. Si no hay patrones claros devuelve arrays vacios. Escribe en espanol, breve y profesional.'
].join(NL);

return [{ json: { usuarios, prompt_global, system_global } }];

const sem = $('Calcular semana').first().json;
const datos = $('Juntar resultados').first().json;
const usuarios = datos.usuarios || [];
const EXCLUIR_GRUPOS = ['CONDUCTORES', 'IT', 'GERENCIA'];

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const resp = $input.first().json;
let global = {};
{
  const t = resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
  if (typeof t === 'string') {
    const a = t.indexOf('{');
    const b = t.lastIndexOf('}');
    try { global = JSON.parse(t.slice(a, b + 1)); } catch (e) { global = { resumen_equipo: t.slice(0, 600) }; }
  }
}

const suma = f => usuarios.reduce((acc, u) => acc + ((u.stats && u.stats[f]) || 0), 0);
const llamadas = usuarios.reduce((acc, u) => acc + Object.values((u.stats && u.stats.herramientas) || {}).reduce((x, h) => x + h.llamadas, 0), 0);

const crudo = $('Open WebUI usuarios').all().map(i => i.json);
const lista = (crudo.length === 1 && Array.isArray(crudo[0].users)) ? crudo[0].users : crudo;
const todosChats = $('Open WebUI chats').all().map(i => i.json).filter(c => c && c.user_id);
const ultimoChat = {};
for (const c of todosChats) { const t = Number(c.updated_at) || 0; if (!ultimoChat[c.user_id] || t > ultimoChat[c.user_id]) ultimoChat[c.user_id] = t; }
const fechaDe = ts => ts ? DateTime.fromSeconds(ts > 1e12 ? ts / 1000 : ts).setZone('Europe/Madrid').toFormat('dd/MM/yyyy') : '';
const nombreGrupos = u => (u.groups || []).map(g => (typeof g === 'string' ? g : g.name)).filter(Boolean);
const candidatos = lista
  .filter(u => u && u.id && u.role !== 'pending')
  .filter(u => !nombreGrupos(u).some(g => EXCLUIR_GRUPOS.includes(g)));
const activos = new Set(usuarios.map(u => u.user_id));
const porNombre = (a, b) => a.nombre.localeCompare(b.nombre);
const sinActividad = candidatos
  .filter(u => !activos.has(u.id) && ultimoChat[u.id])
  .map(u => ({ nombre: u.name, grupos: nombreGrupos(u).join(', '), detalle: 'último chat: ' + fechaDe(ultimoChat[u.id]) }))
  .sort(porNombre);
const nuncaUsado = candidatos
  .filter(u => !ultimoChat[u.id])
  .map(u => ({ nombre: u.name, grupos: nombreGrupos(u).join(', '), detalle: u.last_active_at ? 'último acceso: ' + fechaDe(u.last_active_at) : 'sin accesos' }))
  .sort(porNombre);

const lista_ul = arr => arr.length ? '<ul style="margin:4px 0 8px 18px;padding:0">' + arr.map(x => '<li>' + x + '</li>').join('') + '</ul>' : '';
const bloque = (titulo, html) => html ? '<p style="margin:10px 0 2px;font-weight:bold;color:#333">' + titulo + '</p>' + html : '';
const kpi = (n, t) => '<td style="padding:10px 14px;border:1px solid #ddd;text-align:center"><div style="font-size:22px;font-weight:bold">' + n + '</div><div style="font-size:12px;color:#666">' + t + '</div></td>';
const filaUsuario = x => esc(x.nombre) + (x.grupos ? ' <span style="color:#666">(' + esc(x.grupos) + ')</span>' : '') + ' <span style="color:#999;font-size:12px">— ' + esc(x.detalle) + '</span>';

let html = '<div style="font-family:Arial,sans-serif;max-width:760px;color:#222">';
html += '<h2 style="margin-bottom:2px">Resumen semanal de uso del agente IA</h2>';
html += '<div style="color:#666;margin-bottom:14px">Semana del ' + esc(sem.etiqueta) + '</div>';
html += '<table style="border-collapse:collapse;margin-bottom:14px"><tr>' + kpi(usuarios.length, 'usuarios activos') + kpi(suma('chats'), 'chats') + kpi(suma('mensajes'), 'mensajes') + kpi(llamadas, 'llamadas a herramientas') + kpi(suma('errores_herramienta') + suma('errores_sistema'), 'errores técnicos') + kpi(nuncaUsado.length, 'nunca lo han usado') + '</tr></table>';

if (global.resumen_equipo) {
  html += '<h3 style="border-bottom:1px solid #ddd;padding-bottom:4px">Conclusiones del equipo</h3><p>' + esc(global.resumen_equipo) + '</p>';
  html += bloque('Preguntas que se repiten entre varias personas', lista_ul((global.preguntas_recurrentes_equipo || []).map(q => esc(q.pregunta) + ' <span style="color:#666">(' + esc((q.usuarios || []).join(', ')) + (q.veces ? ', ' + q.veces + ' veces' : '') + ')</span>')));
  html += bloque('Errores frecuentes', lista_ul((global.errores_frecuentes || []).map(e => '<b>' + esc(e.tipo) + ':</b> ' + esc(e.detalle) + (e.sugerencia ? ' <i>→ ' + esc(e.sugerencia) + '</i>' : ''))));
  html += bloque('Mejoras sugeridas', lista_ul((global.mejoras_sugeridas || []).map(esc)));
}

html += '<h3 style="border-bottom:1px solid #ddd;padding-bottom:4px;margin-top:22px">Resumen por persona</h3>';
for (const u of usuarios) {
  const a = u.analisis || {};
  const s = u.stats || {};
  const herr = Object.entries(s.herramientas || {}).map(([n, h]) => esc(n) + ' ×' + h.llamadas + (h.errores ? ' (' + h.errores + ' con error)' : '')).join(', ');
  html += '<div style="border:1px solid #ddd;border-radius:6px;padding:10px 14px;margin:10px 0">';
  html += '<div style="font-size:16px;font-weight:bold">' + esc(u.nombre) + ' <span style="font-weight:normal;color:#666;font-size:13px">' + esc((u.grupos || []).join(', ')) + '</span></div>';
  html += '<div style="color:#666;font-size:12px;margin:2px 0 6px">' + (s.chats || 0) + ' chats · ' + (s.mensajes || 0) + ' mensajes' + (herr ? ' · herramientas: ' + herr : '') + (s.valoraciones_negativas ? ' · ' + s.valoraciones_negativas + ' valoraciones negativas' : '') + '</div>';
  if (u.fallo_llm) html += '<p style="color:#b45309">⚠️ No se pudo analizar la actividad de esta persona (' + esc(u.fallo_llm) + ').</p>';
  if (a.resumen) html += '<p style="margin:4px 0">' + esc(a.resumen) + '</p>';
  if ((a.temas || []).length) html += '<p style="margin:4px 0"><b>Temas:</b> ' + esc((a.temas || []).join(' · ')) + '</p>';
  html += bloque('Preguntas recurrentes', lista_ul((a.preguntas_recurrentes || []).map(q => esc(q.pregunta) + (q.veces ? ' <span style="color:#666">(' + q.veces + ' veces)</span>' : ''))));
  html += bloque('Errores de uso', lista_ul((a.errores_de_uso || []).map(e => '<b>' + esc(e.tipo) + ':</b> ' + esc(e.detalle) + (e.sugerencia ? ' <i>→ ' + esc(e.sugerencia) + '</i>' : ''))));
  html += bloque('Errores técnicos', lista_ul((a.errores_tecnicos || []).map(e => (e.herramienta ? '<b>' + esc(e.herramienta) + ':</b> ' : '') + esc(e.detalle))));
  html += '</div>';
}

if (sinActividad.length) {
  html += '<h3 style="border-bottom:1px solid #ddd;padding-bottom:4px;margin-top:22px">Sin actividad esta semana (' + sinActividad.length + ')</h3><p style="color:#666;font-size:12px;margin:2px 0">Lo han usado alguna vez, pero no esta semana.</p>' + lista_ul(sinActividad.map(filaUsuario));
}
if (nuncaUsado.length) {
  html += '<h3 style="border-bottom:1px solid #ddd;padding-bottom:4px;margin-top:22px">Nunca han usado el agente (' + nuncaUsado.length + ')</h3><p style="color:#666;font-size:12px;margin:2px 0">Usuarios con cuenta y ningún chat. No se incluyen los grupos ' + esc(EXCLUIR_GRUPOS.join(', ')) + '.</p>' + lista_ul(nuncaUsado.map(filaUsuario));
}
html += '<p style="color:#999;font-size:12px;margin-top:20px">Mensaje automático del flujo «INFORMES - Resumen semanal de uso del agente IA» de n8n. Los resúmenes los genera un modelo de IA a partir de los chats de la semana: pueden contener imprecisiones.</p></div>';

return [{ json: { asunto: 'Resumen semanal de uso del agente IA (' + sem.etiqueta + ')', html } }];

const sem = $('Calcular semana').first().json;
const EXCLUIR_GRUPOS = ['CONDUCTORES', 'IT', 'GERENCIA'];
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const crudo = $('Open WebUI usuarios').all().map(i => i.json);
const lista = (crudo.length === 1 && Array.isArray(crudo[0].users)) ? crudo[0].users : crudo;
const todosChats = $('Open WebUI chats').all().map(i => i.json).filter(c => c && c.user_id);
const ultimoChat = {};
for (const c of todosChats) { const t = Number(c.updated_at) || 0; if (!ultimoChat[c.user_id] || t > ultimoChat[c.user_id]) ultimoChat[c.user_id] = t; }
const fechaDe = ts => ts ? DateTime.fromSeconds(ts > 1e12 ? ts / 1000 : ts).setZone('Europe/Madrid').toFormat('dd/MM/yyyy') : '';
const nombreGrupos = u => (u.groups || []).map(g => (typeof g === 'string' ? g : g.name)).filter(Boolean);
const candidatos = lista
  .filter(u => u && u.id && u.role !== 'pending')
  .filter(u => !nombreGrupos(u).some(g => EXCLUIR_GRUPOS.includes(g)));
const porNombre = (a, b) => a.nombre.localeCompare(b.nombre);
const sinActividad = candidatos
  .filter(u => ultimoChat[u.id])
  .map(u => ({ nombre: u.name, grupos: nombreGrupos(u).join(', '), detalle: 'último chat: ' + fechaDe(ultimoChat[u.id]) }))
  .sort(porNombre);
const nuncaUsado = candidatos
  .filter(u => !ultimoChat[u.id])
  .map(u => ({ nombre: u.name, grupos: nombreGrupos(u).join(', '), detalle: u.last_active_at ? 'último acceso: ' + fechaDe(u.last_active_at) : 'sin accesos' }))
  .sort(porNombre);

const lista_ul = arr => arr.length ? '<ul style="margin:4px 0 8px 18px;padding:0">' + arr.map(x => '<li>' + x + '</li>').join('') + '</ul>' : '';
const filaUsuario = x => esc(x.nombre) + (x.grupos ? ' <span style="color:#666">(' + esc(x.grupos) + ')</span>' : '') + ' <span style="color:#999;font-size:12px">— ' + esc(x.detalle) + '</span>';

let html = '<div style="font-family:Arial,sans-serif;max-width:760px;color:#222"><h2>Resumen semanal de uso del agente IA</h2><p style="color:#666">Semana del ' + esc(sem.etiqueta) + '</p><p>Esta semana no ha habido actividad en el agente IA.</p>';
if (sinActividad.length) {
  html += '<h3 style="border-bottom:1px solid #ddd;padding-bottom:4px">Sin actividad esta semana (' + sinActividad.length + ')</h3><p style="color:#666;font-size:12px;margin:2px 0">Lo han usado alguna vez, pero no esta semana.</p>' + lista_ul(sinActividad.map(filaUsuario));
}
if (nuncaUsado.length) {
  html += '<h3 style="border-bottom:1px solid #ddd;padding-bottom:4px;margin-top:22px">Nunca han usado el agente (' + nuncaUsado.length + ')</h3><p style="color:#666;font-size:12px;margin:2px 0">Usuarios con cuenta y ningún chat. No se incluyen los grupos ' + esc(EXCLUIR_GRUPOS.join(', ')) + '.</p>' + lista_ul(nuncaUsado.map(filaUsuario));
